INSERT INTO questions (subject_id, topic_id, question_text, difficulty, type, option_a, option_b, option_c, option_d, correct, explanation, reference_text, image_name, status) SELECT t.subject_id, t.id, '[Demo] Anatomy > Limbs > Upper Limb: question 1. Choose option A.', 'easy', 'single', 'Option A (Upper Limb)', 'Option B (Upper Limb)', 'Option C (Upper Limb)', 'Option D (Upper Limb)', 'A', 'Demo explanation: option A is correct for this sample question.', 'Demo data', '', 'published' FROM topics t JOIN modules m ON m.id = t.module_id JOIN subjects s ON s.id = m.subject_id WHERE s.name = 'Anatomy' AND m.name = 'Limbs' AND t.name = 'Upper Limb' AND NOT EXISTS (SELECT 1 FROM questions y WHERE y.question_text = '[Demo] Anatomy > Limbs > Upper Limb: question 1. Choose option A.');
